from fastapi import APIRouter, Depends, HTTPException
from fastapi.responses import Response
import pycrdt as yjs

router = APIRouter(prefix="/crdt/snapshots")

@router.get("/{document_id}/versions/{version_id}")
async def get_crdt_document_version(
    document_id: str,
    version_id: str,
    snapshot_repo: CRDTSnapshotRepo = Depends(get_snapshot_repo),
    doc_registry: DocumentRegistry = Depends(get_doc_registry),
    current_user: User = Depends(get_current_user)
):
    doc_meta = await doc_registry.get_document(document_id)
    if not doc_meta or doc_meta.tenant_id != current_user.tenant_id:
        raise HTTPException(status_code=404, detail="Document not found")

    snapshot = await snapshot_repo.find_snapshot(document_id, version_id)
    if not snapshot:
        raise HTTPException(status_code=404, detail="CRDT document snapshot not found")

    return Response(
        content=snapshot.binary_state,
        media_type="application/octet-stream",
        headers={"X-Snapshot-Created-By": snapshot.created_by_user_id}
    )
